#include <vector>
#include <iostream>

// Custom container that mimics a simple wrapper around std::vector
template<typename T>
class MyContainer {
public:
    std::vector<T> data;
    void add(const T& value) { data.push_back(value); }
    auto begin() { return data.begin(); }
    auto end() { return data.end(); }
};

// Custom algorithm that counts elements satisfying a predicate
template<typename Container, typename Predicate>
size_t count_if(const Container& c, Predicate pred) {
    size_t count = 0;
    for (const auto& element : c) {
        if (pred(element)) {
            ++count;
        }
    }
    return count;
}

int main() {
    MyContainer<int> myInts;
    myInts.add(1);
    myInts.add(2);
    myInts.add(3);
    myInts.add(4);

    // Use custom algorithm to count even numbers
    size_t evenCount = count_if(myInts, [](int x) { return x % 2 == 0; });
    std::cout << "Number of even elements: " << evenCount << std::endl;
    return 0;
}
